<script lang="ts">import Shell from '$lib/components/Shell.svelte';import {ZoomIn,ZoomOut,Maximize} from 'lucide-svelte';let {data}=$props();const d=$derived(data.snapshot);let selected=$state<any>(null);let scale=$state(1);const cols:any={sale:0,fee:1,refund:1,dispute:1,fx_conversion:2,payout:3,bank_deposit:4};const positions=$derived.by(()=>{const map=new Map();const rows=new Map();for(const e of d.events){const c=cols[e.kind];const r=rows.get(c)??0;rows.set(c,r+1);map.set(e.id,{x:45+c*210,y:75+r*88})}return map});const money=(e:any)=>new Intl.NumberFormat('en-US',{style:'currency',currency:e.currency}).format(e.amount/100);const related=()=>selected?d.edges.filter((e:any)=>e.fromEventId===selected.id||e.toEventId===selected.id):[];</script>
<Shell><div class="graph-page"><header class="page-head"><h1>Graph</h1><span class="status-pill"><i></i>{d.edges.filter((e:any)=>e.status!=='rejected').length} connections</span></header><div class="legend"><span><i class="auto"></i>Auto</span><span><i class="review"></i>Review</span></div><div class="graph-layout"><div class="canvas card">{#if !d.events.length}<p class="blank">Import on Overview first.</p>{:else}<div class="tools"><button onclick={()=>scale=Math.min(1.4,scale+.1)} aria-label="Zoom in"><ZoomIn/></button><button onclick={()=>scale=Math.max(.6,scale-.1)} aria-label="Zoom out"><ZoomOut/></button><button onclick={()=>scale=1} aria-label="Reset zoom"><Maximize/></button></div><div class="stage" style:transform={`scale(${scale})`}><div class="columns">{#each ['Sales','Adjustments','FX','Payouts','Bank'] as l}<span>{l}</span>{/each}</div><svg aria-hidden="true" viewBox="0 0 950 590" preserveAspectRatio="none">{#each d.edges.filter((x:any)=>x.status!=='rejected') as edge}{@const a=positions.get(edge.fromEventId)}{@const b=positions.get(edge.toEventId)}{#if a&&b}<path d={`M${a.x+155},${a.y+29} C${a.x+180},${a.y+29} ${b.x-25},${b.y+29} ${b.x},${b.y+29}`} class:review={edge.status==='review'}/>{/if}{/each}</svg>{#each d.events as e}{@const p=positions.get(e.id)}<button class="node {e.source}" class:selected={selected?.id===e.id} style:left={`${p.x}px`} style:top={`${p.y}px`} onclick={()=>selected=e}><span>{e.source} · {e.kind.replace('_',' ')}</span><strong>{money(e)}</strong><small>{e.occurredAt.slice(0,10)}</small></button>{/each}</div>{/if}</div><aside class="inspector card">{#if selected}<header><span class="chip">{selected.source}</span><h2>{selected.kind.replace('_',' ')}</h2><strong>{money(selected)}</strong></header><dl><div><dt>Event ID</dt><dd>{selected.id}</dd></div><div><dt>Occurred</dt><dd>{selected.occurredAt.slice(0,10)}</dd></div><div><dt>External reference</dt><dd>{selected.externalRef??'—'}</dd></div><div><dt>Payout reference</dt><dd>{selected.payoutRef??'—'}</dd></div></dl><section><h3>Connections</h3>{#if !related().length}<p>None</p>{:else}{#each related() as edge}<article><b>{edge.relationship.replace('_',' ')}</b><span class:warn={edge.status==='review'}>{edge.status} · {(edge.confidence*100).toFixed(0)}%</span><small>{edge.reasons.join(' · ')}</small></article>{/each}{/if}</section>{:else}<p class="blank">Select an event</p>{/if}</aside></div></div></Shell>
<style>.graph-page{display:flex;flex-direction:column;gap:12px}.legend{display:flex;gap:18px;font-size:10px;color:var(--muted)}.legend span{display:flex;align-items:center;gap:6px}.legend i{width:18px;height:2px;background:var(--green)}.legend i.review{background:var(--amber);border-top:1px dashed white}.graph-layout{display:grid;grid-template-columns:minmax(0,1fr) 260px;gap:14px}.canvas{height:560px;overflow:auto;position:relative;background-color:#fafbf8;background-image:radial-gradient(#d7ddd7 1px,transparent 1px);background-size:20px 20px}.blank{margin:0;padding:16px;font-size:13px;color:var(--muted)}.stage{position:relative;width:980px;height:610px;transform-origin:top left;transition:transform .15s}.columns{position:absolute;top:22px;left:45px;right:0;display:grid;grid-template-columns:repeat(5,210px);font:9px 'DM Mono';text-transform:uppercase;letter-spacing:.11em;color:#8c968f}.stage svg{position:absolute;inset:0;width:950px;height:590px;overflow:visible}.stage path{fill:none;stroke:var(--green);stroke-width:1.5}.stage path.review{stroke:var(--amber);stroke-dasharray:5 4}.node{position:absolute;width:155px;height:59px;text-align:left;border:1px solid #d7ded7;border-left:3px solid var(--green);border-radius:8px;background:#fff;padding:8px 10px;box-shadow:0 3px 9px rgba(16,25,20,.05)}.node.stripe{border-left-color:#635bff}.node.gumroad{border-left-color:#dc60c5}.node.dodo{border-left-color:#c99625}.node.bank{border-left-color:#117aca}.node.selected{outline:3px solid rgba(31,104,72,.18);border-color:var(--green)}.node span,.node small{display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font:7px 'DM Mono';text-transform:uppercase;color:var(--muted)}.node strong{display:block;font:500 11px 'DM Mono';margin:6px 0}.tools{position:sticky;z-index:5;top:12px;left:12px;width:34px;display:grid;background:#fff;border:1px solid var(--line);border-radius:7px;overflow:hidden}.tools button{width:32px;height:32px;background:#fff;border:0;border-bottom:1px solid var(--line)}.tools button:last-child{border:0}.tools :global(svg){width:14px}.inspector{padding:16px;min-height:560px}.inspector header{border-bottom:1px solid var(--line);padding-bottom:14px}.inspector h2{text-transform:capitalize;font-size:16px;margin:10px 0 6px}.inspector header strong{font:500 20px 'DM Mono'}.inspector dl{display:grid;gap:12px;margin:16px 0}.inspector dt,.inspector h3{font:9px 'DM Mono';text-transform:uppercase;letter-spacing:.1em;color:var(--muted)}.inspector dd{font:10px 'DM Mono';margin:4px 0;overflow-wrap:anywhere}.inspector section{border-top:1px solid var(--line);padding-top:12px}.inspector article{display:grid;gap:5px;border:1px solid var(--line);padding:10px;margin-top:8px;border-radius:7px}.inspector article b{font-size:11px;text-transform:capitalize}.inspector article span{font:9px 'DM Mono';color:var(--green)}.inspector article small{color:var(--muted);line-height:1.5}@media(max-width:1100px){.graph-layout{grid-template-columns:1fr}.inspector{min-height:160px}.canvas{height:480px}}</style>
